import { ApiError, type Client, type FetchInit, type FetchLike, type LookupResult, type ShortenResult, type Stats } from './types.ts';

export function createClient(base: string, fetch: FetchLike): Client {
  const root = base.replace(/\/+$/, '');

  async function call<T>(path: string, init: FetchInit): Promise<T> {
    const res = await fetch(root + path, init);
    let body: unknown;
    try {
      body = await res.json();
    } catch {
      body = undefined;
    }
    if (res.status < 200 || res.status > 299) {
      const msg = (body as { error?: unknown } | undefined)?.error;
      throw new ApiError(res.status, typeof msg === 'string' ? msg : `HTTP ${res.status}`);
    }
    return body as T;
  }

  return {
    shorten: (url) =>
      call<ShortenResult>('/shorten', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ url }),
      }),
    lookup: (code) => call<LookupResult>(`/lookup/${encodeURIComponent(code)}`, { method: 'GET' }),
    stats: () => call<Stats>('/stats', { method: 'GET' }),
  };
}
